const fmtDateTime=d=>{if(!d)return '—';const text=String(d),date=new Date(text+(text.length===10?'T12:00:00':''));return text.length===10?fmtDate(text):date.toLocaleString('en-US',{month:'short',day:'numeric',year:'numeric',hour:'numeric',minute:'2-digit'})};
