const numericValue=value=>{const values=String(value||'').replace(/,/g,'').match(/\d+(?:\.\d+)?/g)||[];return values.length?Number(values.at(-1)):0};
function propertyMatch(contact,listing){const desiredBeds=Number(contact.bedrooms||0),listingBeds=Number(listing.bedrooms||0),budgetMax=Number(contact.budget_max||numericValue(contact.budget)),price=Number(listing.current_price||0),wantedArea=String(contact.area||'').trim().toLowerCase(),listingArea=String(listing.area||listing.address||'').toLowerCase(),wantedSubdivision=String(contact.subdivision||'').trim().toLowerCase(),listingSubdivision=String(listing.subdivision||'').trim().toLowerCase(),wantedPool=String(contact.pool||''),listingPool=String(listing.pool||''),feature=String(contact.important_feature||'').trim().toLowerCase(),features=String(listing.important_features||listing.marketing_notes||'').toLowerCase();const checks=[];if(desiredBeds)checks.push([listingBeds>=desiredBeds,35,`${listingBeds||'—'} bedrooms vs ${desiredBeds}+ wanted`]);if(budgetMax)checks.push([price<=budgetMax,30,`${fmtMoney(price)} vs ${fmtMoney(budgetMax)} maximum`]);if(wantedArea)checks.push([listingArea.includes(wantedArea)||wantedArea.split(/[,/]/).some(x=>x.trim()&&listingArea.includes(x.trim())),20,`Area: ${contact.area}`]);if(wantedSubdivision)checks.push([listingSubdivision.includes(wantedSubdivision)||wantedSubdivision.split(/[,/]/).some(x=>x.trim()&&listingSubdivision.includes(x.trim())),20,`Subdivision: ${contact.subdivision}`]);if(wantedPool==='Yes')checks.push([listingPool==='Yes',10,'Pool required']);if(feature)checks.push([features.includes(feature)||feature.split(/[,/]/).some(x=>x.trim().length>2&&features.includes(x.trim())),5,`Feature: ${contact.important_feature}`]);const possible=checks.reduce((n,x)=>n+x[1],0),earned=checks.reduce((n,x)=>n+(x[0]?x[1]:0),0),score=possible?Math.round(earned/possible*100):0;return {score,reasons:checks.filter(x=>x[0]).map(x=>x[2]),misses:checks.filter(x=>!x[0]).map(x=>x[2]),eligible:possible>0&&score>=60&&(!desiredBeds||listingBeds>=desiredBeds)}}
function matchingBuyers(listing){const active=new Set((state.data.opportunities||[]).filter(x=>x.type==='buyer'&&x.status!=='closed'&&!['Closed','Nurture/Lost'].includes(x.stage)).map(x=>x.contact_id));return (state.data.contacts||[]).filter(c=>(c.roles||[]).includes('Buyer')&&(!active.size||active.has(c.id))).map(contact=>({contact,...propertyMatch(contact,listing)})).filter(x=>x.eligible).sort((a,b)=>b.score-a.score)}
