function assistantMessage(role,content,action=''){return `<article class="assistant-message ${role}"><div class="assistant-avatar">${role==='user'?'EH':'✦'}</div><div class="assistant-bubble">${role==='user'?`<p>${esc(content)}</p>`:content}${action?`<div class="assistant-actions">${action}</div>`:''}</div></article>`}
function bindAssistantActions(){$$('.assistant-route').forEach(b=>b.onclick=()=>go(b.dataset.route));$$('.assistant-contact').forEach(b=>b.onclick=()=>showContact(Number(b.dataset.contact)));$$('.assistant-task').forEach(b=>b.onclick=()=>openForm('tasks',{contact_id:Number(b.dataset.contact)}));$$('.assistant-new-task').forEach(b=>b.onclick=()=>openForm('tasks',{title:b.dataset.taskTitle||'',due_at:new Date(Date.now()+864e5).toISOString().slice(0,11)+'09:00'}));$$('.assistant-review-task').forEach(b=>b.onclick=()=>{const task=JSON.parse(decodeURIComponent(b.dataset.assistantTask));delete task.summary;openForm('tasks',task)});$$('.assistant-review-contact').forEach(b=>b.onclick=()=>openForm('contacts',JSON.parse(decodeURIComponent(b.dataset.assistantContact))));$$('.assistant-review-listing').forEach(b=>b.onclick=()=>openForm('listings',JSON.parse(decodeURIComponent(b.dataset.assistantListing)),Number(b.dataset.listingId)));$$('.assistant-confirm-activity').forEach(b=>b.onclick=async()=>{if(b.disabled)return;b.disabled=true;try{const activity=JSON.parse(decodeURIComponent(b.dataset.assistantAction));await api('/activities',{method:'POST',body:JSON.stringify(activity)});state.lastAssistantAction={status:'saved',summary:activity.summary};state.assistantHistory.push({role:'assistant',content:`<p><strong>Saved.</strong> ${esc(activity.summary)}.</p><p>The contact’s last-contact date was updated.</p>`,action:`<button class="btn assistant-contact" data-contact="${activity.contact_id}">Open contact</button>`});await load('contacts','activities');renderAssistantHistory();toast('Completed activity saved')}catch(err){b.disabled=false;toast(err.message,true)}});$$('.assistant-cancel-activity').forEach(b=>b.onclick=()=>{if(state.lastAssistantAction)state.lastAssistantAction.status='cancelled';state.assistantHistory.push({role:'assistant',content:'<p>Cancelled. Nothing was saved.</p>'});renderAssistantHistory()})}
function renderAssistantHistory(){const log=$('#assistantLog');if(!log)return;log.innerHTML=state.assistantHistory.length?state.assistantHistory.map(x=>assistantMessage(x.role,x.content,x.action)).join(''):assistantMessage('assistant','<p><strong>Hi Eric.</strong> I can analyze your CRM, prioritize your day, explain what needs attention, and prepare changes for your review.</p><p>I will not save, send, delete, or change anything without your approval.</p>');bindAssistantActions();log.scrollTop=log.scrollHeight}
async function submitAssistantPrompt(prompt){const text=String(prompt||'').trim();if(!text)return;state.assistantHistory.push({role:'user',content:text});const reply=assistantReply(text);state.assistantHistory.push({role:'assistant',content:reply.html,action:reply.action});renderAssistantHistory();$('#assistantInput').value=''}
let assistantRecognition=null;
function assistantVoiceStatus(message,error=false){const status=$('#assistantVoiceStatus');if(!status)return;status.textContent=message||'';status.classList.toggle('error',error)}
