async function previewListingCsv(event){const file=event.target.files?.[0];if(!file)return;const rows=parseCsv(await file.text());const preview=$('#listingCsvPreview');if(rows.length<2){preview.innerHTML='<div class="csv-error">No listing rows were found in that CSV.</div>';return}const headers=rows[0].map(x=>x.replace(/^\uFEFF/,'')),items=rows.slice(1).map(values=>listingFromCsv(headers,values)).filter(item=>item.address);if(!items.length){preview.innerHTML='<div class="csv-error">I could not find a property address column. Try the template or export a report that includes the full address.</div>';return}const prepared=items.map(item=>({item,existing:matchImportedListing(item)}));const updates=prepared.filter(x=>x.existing).length;preview.innerHTML=`<div class="csv-summary"><strong>${prepared.length}</strong> listing${prepared.length===1?'':'s'} ready · ${prepared.length-updates} new · ${updates} update${updates===1?'':'s'}</div><div class="table-wrap csv-preview-table"><table><thead><tr><th>Action</th><th>Property</th><th>MLS</th><th>Price</th><th>Details</th></tr></thead><tbody>${prepared.map(({item,existing})=>`<tr><td>${badge(existing?'Update':'Add',existing?'gold':'gray')}</td><td><b>${esc(item.address)}</b></td><td>${esc(item.mls||'—')}</td><td>${fmtMoney(item.current_price)}</td><td>${item.bedrooms||'—'} BR · ${item.bathrooms||'—'} BA · ${item.square_feet?Number(item.square_feet).toLocaleString():'—'} SF</td></tr>`).join('')}</tbody></table></div><p class="csv-note">Existing listings are matched by MLS number, or by address when no MLS number is present. Blank cells will not erase existing details.</p><div class="form-actions"><button type="button" class="btn" id="backCsv">Choose another file</button><button type="button" class="btn primary" id="saveCsvListings">Import ${prepared.length} listing${prepared.length===1?'':'s'}</button></div>`;$('#backCsv').onclick=()=>openListingCsvImport();$('#saveCsvListings').onclick=()=>importListingCsv(prepared)}
async function importListingCsv(prepared){const button=$('#saveCsvListings');button.disabled=true;button.textContent='Importing…';let added=0,updated=0;try{for(const entry of prepared){const existing=matchImportedListing(entry.item);if(existing){await api('/listings/'+existing.id,{method:'PUT',body:JSON.stringify(mergeImportedListing(existing,entry.item))});updated++}else{const saved=await api('/listings',{method:'POST',body:JSON.stringify(entry.item)});state.data.listings.push(saved);added++}}closeModal();toast(`${added} listing${added===1?'':'s'} added · ${updated} updated`);await go('listings')}catch(error){button.disabled=false;button.textContent='Try import again';toast(error.message||'Import failed',true)}}
function contactFromCsv(headers,values){const row=Object.fromEntries(headers.map((header,index)=>[csvHeaderKey(header),String(values[index]||'').trim()])),read=(...names)=>names.map(name=>row[csvHeaderKey(name)]).find(Boolean)||'';let first=read('first-name','first name','firstname'),last=read('last-name','last name','lastname');const combined=read('primary_name','primary name','name');if((!first||!last)&&combined){const parts=combined.split(/\s+/).filter(Boolean);last=last||parts.pop()||'';first=first||parts.join(' ')}const phone=read('phone-mobile','mobile phone','mobile','cell phone','cell','phone-primary','phone'),email=read('primary_email','primary email','email'),street=read('address-home-street1','home street','street address'),city=read('address-home-city','home city','city'),region=read('address-home-state','home state','state'),zip=read('address-home-zip','home zip','zip'),address=[street,[city,region].filter(Boolean).join(', '),zip].filter(Boolean).join(' '),notes=address?`Home address: ${address}`:'';return {first_name:first,last_name:last,phone,email,preferred_contact:phone?'Text':'Email',source:'Other',roles:[],tags:['Flexmls Import'],notes}}
const normalizedContactPhone=value=>String(value||'').replace(/\D/g,'');
