function matchImportedContact(item,contacts=state.data.contacts||[]){const email=normalizedContactText(item.email),phone=normalizedContactPhone(item.phone),name=`${normalizedContactText(item.first_name)}|${normalizedContactText(item.last_name)}`;return contacts.find(existing=>(email&&normalizedContactText(existing.email)===email)||(phone.length>=7&&normalizedContactPhone(existing.phone)===phone)||(name!=='|'&&`${normalizedContactText(existing.first_name)}|${normalizedContactText(existing.last_name)}`===name))}
