async function previewContactCsv(input){const file=input.files?.[0];if(!file)return;const rows=parseCsv(await file.text()),preview=$('#contactCsvPreview');if(rows.length<2){preview.innerHTML='<div class="csv-error">No contact rows were found in that CSV.</div>';return}const headers=rows[0].map(x=>x.replace(/^\uFEFF/,'')),raw=rows.slice(1).map(values=>contactFromCsv(headers,values)).filter(item=>item.first_name&&item.last_name),unique=new Map();for(const item of raw){const key=normalizedContactText(item.email)||normalizedContactPhone(item.phone)||`${normalizedContactText(item.first_name)}|${normalizedContactText(item.last_name)}`;if(!unique.has(key))unique.set(key,item)}const items=[...unique.values()];if(!items.length){preview.innerHTML='<div class="csv-error">I could not find usable first and last names in this file.</div>';return}const prepared=items.map(item=>({item,existing:matchImportedContact(item)})),updates=prepared.filter(x=>x.existing).length;preview.innerHTML=`<div class="csv-summary"><strong>${prepared.length}</strong> contact${prepared.length===1?'':'s'} ready · ${prepared.length-updates} new · ${updates} matched</div><div class="table-wrap csv-preview-table"><table><thead><tr><th>Action</th><th>Contact</th><th>Email</th><th>Cell phone</th></tr></thead><tbody>${prepared.map(({item,existing})=>`<tr><td>${badge(existing?'Update':'Add',existing?'gold':'gray')}</td><td><b>${esc(item.first_name)} ${esc(item.last_name)}</b></td><td>${esc(item.email||'—')}</td><td>${esc(item.phone||'—')}</td></tr>`).join('')}</tbody></table></div><p class="csv-note">Matched contacts keep their current CRM details; the importer fills blank fields and adds the “Flexmls Import” tag. New contacts are added without automatically placing them in the buyer or seller pipeline.</p><div class="form-actions"><button type="button" class="btn" id="backContactCsv">Choose another file</button><button type="button" class="btn primary" id="saveCsvContacts">Import ${prepared.length} contact${prepared.length===1?'':'s'}</button></div>`;$('#backContactCsv').onclick=openContactCsvImport;$('#saveCsvContacts').onclick=()=>importContactCsv(prepared)}
async function importContactCsv(prepared){const button=$('#saveCsvContacts');button.disabled=true;button.textContent='Importing…';let added=0,updated=0;try{for(const entry of prepared){const existing=matchImportedContact(entry.item);if(existing){const saved=await api('/contacts/'+existing.id,{method:'PUT',body:JSON.stringify(mergeImportedContact(existing,entry.item))});Object.assign(existing,saved);updated++}else{const saved=await api('/contacts',{method:'POST',body:JSON.stringify(entry.item)});state.data.contacts.push(saved);added++}}closeModal();toast(`${added} contact${added===1?'':'s'} added · ${updated} updated`);await go('contacts')}catch(error){button.disabled=false;button.textContent='Try import again';toast(error.message||'Import failed',true)}}
