async function openListingMatches(listing){await load('contacts','opportunities','listings');const matches=matchingBuyers(listing);$('#modalKicker').textContent='BUYER PROPERTY MATCHING';$('#modalTitle').textContent=listing.address;$('#modalForm').innerHTML=`<div class="match-panel"><div class="match-summary"><strong>${matches.length}</strong><span>active buyer${matches.length===1?'':'s'} match this property</span></div>${matches.length?matches.map(({contact,score,reasons,misses})=>`<article class="match-card"><div><h3>${esc(contact.first_name)} ${esc(contact.last_name)}</h3><p>${reasons.map(esc).join(' · ')}</p>${misses.length?`<small>Review: ${misses.map(esc).join(' · ')}</small>`:''}</div><div class="match-actions">${badge(`${score}%`,'gold')}<button type="button" class="btn open-match-contact" data-id="${contact.id}">Profile</button><button type="button" class="btn primary draft-property-match" data-id="${contact.id}">Create draft</button></div></article>`).join(''):empty('No matching buyers yet','Add buyer budget, minimum bedrooms, area, subdivision, pool, or important features to improve matching.')}<div class="form-actions"><button type="button" class="btn" id="closeMatches">Close</button><button type="button" class="btn primary" id="matchesQr">Open-house QR</button></div></div>`;$('#modal').classList.remove('hidden');$('#closeMatches').onclick=closeModal;$('#matchesQr').onclick=()=>openOpenHouseQr(listing);$$('.open-match-contact').forEach(b=>b.onclick=()=>{closeModal();showContact(Number(b.dataset.id))});$$('.draft-property-match').forEach(b=>b.onclick=()=>savePropertyDraft(state.data.contacts.find(c=>c.id===Number(b.dataset.id)),listing))}
function openOpenHouseQr(listing){const url=new URL('./open-house.html',location.href);url.searchParams.set('listing',String(listing.id));url.searchParams.set('address',listing.address);const preview=new URL(url);preview.searchParams.set('preview','1');const qr=`https://quickchart.io/qr?size=340&margin=2&text=${encodeURIComponent(url.href)}`;$('#modalKicker').textContent='OPEN-HOUSE SIGN-IN';$('#modalTitle').textContent=listing.address;$('#modalForm').innerHTML=`<div class="qr-panel"><img src="${esc(qr)}" alt="Open-house sign-in QR code"><h3>Scan to sign in</h3><p>Visitors can enter their contact information, timeframe, and property preferences. After signing in, they will see the public marketing page for this listing.</p><input id="openHouseLink" value="${esc(url.href)}" readonly><div class="form-actions"><button type="button" class="btn" id="closeQr">Close</button><a class="btn" href="${esc(preview.href)}" target="_blank" rel="noopener">Preview visitor page</a><button type="button" class="btn" id="copyQrLink">Copy link</button><button type="button" class="btn primary" id="shareQrLink">Share</button></div></div>`;$('#modal').classList.remove('hidden');$('#closeQr').onclick=closeModal;$('#copyQrLink').onclick=async()=>{await navigator.clipboard.writeText(url.href);toast('Open-house link copied')};$('#shareQrLink').onclick=async()=>{if(navigator.share)await navigator.share({title:`Open house — ${listing.address}`,text:'Please sign in for the open house.',url:url.href});else{await navigator.clipboard.writeText(url.href);toast('Link copied')}}}
async function drawContactMatches(){if(!state.contact)return;await load('listings');const matches=matchingListings(state.contact);$('#contactPanel').innerHTML=`<div class="card-head"><div><h2>Matching listings</h2><small>${matches.length} current match${matches.length===1?'':'es'}</small></div></div><div class="match-panel embedded">${matches.length?matches.map(({listing,score,reasons})=>`<article class="match-card"><div><h3>${esc(listing.address)}</h3><p>${fmtMoney(listing.current_price)} · ${reasons.map(esc).join(' · ')}</p></div><div class="match-actions">${badge(`${score}%`,'gold')}<button class="btn create-contact-property-draft" data-id="${listing.id}">Create draft</button></div></article>`).join(''):empty('No matching listings','Add buyer criteria or listing details to generate matches.')}</div>`;$$('.create-contact-property-draft').forEach(b=>b.onclick=()=>savePropertyDraft(state.contact,state.data.listings.find(x=>x.id===Number(b.dataset.id))))}
async function openSuggestedDraftForm(contact=state.contact){await load('contacts');const selected=contact||state.data.contacts[0];if(!selected)return toast('Add a contact before creating a draft',true);const suggestion=draftSuggestion(selected);$('#modalKicker').textContent='MESSAGE RECOMMENDATION';$('#modalTitle').textContent='Create draft';$('#modalForm').innerHTML=`<div class="form-grid"><label class="field"><span>Contact</span><select id="draftContact">${state.data.contacts.map(c=>`<option value="${c.id}" ${c.id===selected.id?'selected':''}>${esc(c.first_name)} ${esc(c.last_name)}</option>`).join('')}</select></label><label class="field"><span>Type</span><select id="draftChannel"><option>Email</option><option>Text</option></select></label><label class="field full"><span>Subject</span><input id="draftSubject" value="${esc(suggestion.subject)}"></label><label class="field full"><span>Message</span><textarea id="draftBody">${esc(suggestion.body)}</textarea></label><div class="field full"><small>Nothing is sent automatically. The draft stays here until you review it.</small></div><div class="form-actions"><button type="button" class="btn" id="cancelDraft">Cancel</button><button type="button" class="btn primary" id="saveSuggestedDraft">Save draft</button></div></div>`;$('#modal').classList.remove('hidden');$('#cancelDraft').onclick=closeModal;$('#draftContact').onchange=()=>{const c=state.data.contacts.find(x=>x.id===Number($('#draftContact').value)),s=draftSuggestion(c,$('#draftChannel').value);$('#draftSubject').value=s.subject;$('#draftBody').value=s.body};$('#saveSuggestedDraft').onclick=async()=>{await api('/communication_drafts',{method:'POST',body:JSON.stringify({contact_id:Number($('#draftContact').value),channel:$('#draftChannel').value,subject:$('#draftSubject').value,body:$('#draftBody').value,status:'draft',source:'Manual recommendation'})});closeModal();toast('Draft saved for review');go('inbox')}}
async function openDraft(id){await load('communication_drafts','contacts','tasks');const draft=state.data.communication_drafts.find(x=>x.id===id),contact=state.data.contacts.find(x=>x.id===draft?.contact_id);if(!draft)return;$('#modalKicker').textContent='REVIEW BEFORE SENDING';$('#modalTitle').textContent=`${draft.channel} draft`;$('#modalForm').innerHTML=`<div class="form-grid"><div class="field full"><span>Contact</span><b>${esc(contact?`${contact.first_name} ${contact.last_name}`:'Unassigned')}</b></div><label class="field"><span>Type</span><select id="reviewChannel"><option ${draft.channel==='Email'?'selected':''}>Email</option><option ${draft.channel==='Text'?'selected':''}>Text</option></select></label><label class="field full"><span>Subject</span><input id="reviewSubject" value="${esc(draft.subject||'')}"></label><label class="field full"><span>Message</span><textarea id="reviewBody">${esc(draft.body||'')}</textarea></label><div class="field full"><small>Email drafts open in Gmail for ${CRM_EMAIL_ACCOUNT}. Text drafts open in Messages. Opening the app does not mark anything complete. After you send it, return here and choose Mark sent &amp; complete.</small></div><div class="form-actions draft-actions"><button type="button" class="btn danger" id="deleteDraft">Delete draft</button><button type="button" class="btn" id="saveDraft">Save draft</button><a class="btn primary" id="openDraftApp" target="_blank" rel="noopener">Open in app</a><button type="button" class="btn" id="markDraftSent">Mark sent &amp; complete</button></div></div>`;$('#modal').classList.remove('hidden');const values=()=>({channel:$('#reviewChannel').value,subject:$('#reviewSubject').value,body:$('#reviewBody').value}),updateLink=()=>{const v=values(),email=contact?.email||'',phone=phoneHref(contact?.phone),href=v.channel==='Email'?gmailComposeUrl(email,v.subject,v.body):`sms:${phone}?&body=${encodeURIComponent(v.body)}`;$('#openDraftApp').href=href;$('#openDraftApp').textContent=v.channel==='Email'?'Open in Gmail':'Open in Messages'};['reviewChannel','reviewSubject','reviewBody'].forEach(key=>$(`#${key}`).oninput=updateLink);updateLink();$('#deleteDraft').onclick=async()=>{if(!confirm(`Delete the draft “${draft.subject||`${draft.channel} draft`}”? This cannot be undone.`))return;await api('/communication_drafts/'+id,{method:'DELETE'});closeModal();toast('Draft deleted');go('inbox')};$('#saveDraft').onclick=async()=>{await api('/communication_drafts/'+id,{method:'PUT',body:JSON.stringify(values())});toast('Draft saved')};$('#openDraftApp').onclick=()=>{api('/communication_drafts/'+id,{method:'PUT',body:JSON.stringify(values())});toast('Draft opened — send it, then mark it complete')};$('#markDraftSent').onclick=async()=>{const v=values(),completedAt=new Date().toISOString();await api('/communication_drafts/'+id,{method:'PUT',body:JSON.stringify({...v,status:'sent',sent_at:completedAt})});await api('/activities',{method:'POST',body:JSON.stringify({contact_id:draft.contact_id,type:v.channel,direction:'Outgoing',subject:v.subject,body:v.body,occurred_at:completedAt,metadata:{draft_id:draft.id,task_id:draft.linked_task_id||null}})});const sourceTask=String(draft.source||'').includes(':')?String(draft.source).split(':').slice(1).join(':').trim():'';const linkedTask=(draft.linked_task_id?(state.data.tasks||[]).find(task=>Number(task.id)===Number(draft.linked_task_id)&&task.status==='open'):null)||(sourceTask?(state.data.tasks||[]).find(task=>!task._calendar&&task.status==='open'&&Number(task.contact_id)===Number(draft.contact_id)&&String(task.title||'').trim().toLowerCase()===sourceTask.toLowerCase()):null);if(linkedTask)await api('/tasks/'+linkedTask.id,{method:'PUT',body:JSON.stringify({status:'completed',completed_at:completedAt})});closeModal();toast(linkedTask?'Communication sent and follow-up completed':'Communication marked sent');go('inbox')}}
