async function pipeline(type,stages){await load('opportunities');const a=state.data.opportunities.filter(x=>x.type===type);$('#app').innerHTML=header('OPPORTUNITIES',`${type==='buyer'?'Buyer':'Seller'} pipeline`,`${a.length} opportunities across ${stages.length} stages.`,`<button class="btn primary" data-add="opportunities" data-type="${type}">＋ Add opportunity</button>`)+`<div class="pipeline">${stages.map(stage=>`<section class="column"><div class="column-head"><span>${stage}</span>${badge(a.filter(x=>x.stage===stage).length,'gray')}</div>${a.filter(x=>x.stage===stage).map(x=>`<article class="opp clickable" data-contact="${x.contact_id}" title="Open ${esc(x.contact_name)}"><h3>${esc(x.contact_name)}</h3><p>${esc(x.title||`${type} opportunity`)}</p><label class="stage-control">Estimated value<input class="opp-value" data-opportunity="${x.id}" type="number" min="0" step="1000" value="${Number(x.value||0)}"></label><label class="stage-control">Stage<select class="opp-stage" data-opportunity="${x.id}">${stages.map(s=>`<option value="${s}" ${s===x.stage?'selected':''}>${s}</option>`).join('')}</select></label></article>`).join('')}</section>`).join('')}</div>`;bind();}
function taskRow(x){if(x._followup)return `<div class="list-item"><button class="icon followup-complete" data-contact-id="${x.contact_id}" title="Mark follow-up complete">○</button><div class="grow"><p>Follow-up — ${esc(x.contact_name)}</p><small>${fmtDateTime(x.due_at)} · Contact follow-up</small></div><button class="btn followup-open" data-contact-id="${x.contact_id}">Open contact</button>${badge('Follow-up','gold')}</div>`;if(x._calendar)return `<div class="list-item"><button class="icon milestone-complete" data-transaction="${x.transaction_id}" data-milestone="${x.milestone_key}" title="${x.status==='completed'?'Completed':'Mark complete'}">${x.status==='completed'?'●':'○'}</button><div class="grow"><p>${esc(x.title)}</p><small>${esc(x.contact_name||'Transaction')} · ${fmtDateTime(x.due_at)}</small></div>${calendarAction(x.title,x.due_at,x.contact_name||'CRM transaction milestone','Add')}${badge(x.status==='completed'?'Completed':'Transaction',x.status==='completed'?'gray':'gold')}</div>`;const address=taskListingAddress(x);return `<div class="list-item"><button class="icon task-complete" data-id="${x.id}" title="Complete">${x.status==='completed'?'●':'○'}</button><div class="grow"><p>${esc(x.title)}</p><small>${esc(x.contact_name||'General')}${address?` · ${esc(address)}`:''} · ${taskDateRange(x)} · ${esc(x.priority)}${x.completed_at?` · Completed ${fmtDateTime(x.completed_at)}`:''}${x.status!=='completed'&&Number(x.reminder_minutes)>0?` · Reminder ${esc(reminderLabel(x.reminder_minutes))}`:''}</small></div>${calendarAction(`${x.title}${address?` — ${address}`:''}`,x.due_at,[x.contact_name,address,x.notes].filter(Boolean).join(' — '),'Add',x.end_at)}<button class="btn task-edit" data-id="${x.id}">Edit</button><button class="btn danger task-delete" data-id="${x.id}">Delete</button>${badge(x.status==='completed'?'Completed':x.priority,x.priority==='High'?'red':'gray')}</div>`}
