function openQuickContactNote(id){const contact=(state.data.contacts||[]).find(c=>Number(c.id)===Number(id));if(!contact)return toast('Contact not found',true);$('#modalKicker').textContent='QUICK NOTE';$('#modalTitle').textContent=`Note for ${contact.first_name} ${contact.last_name}`;$('#modalForm').innerHTML=`<div class="form-grid quick-note-form"><label class="field full"><span>Note</span><textarea id="quickContactNote" name="note" placeholder="Type your note here…" required></textarea><small>This note will appear in the contact’s timeline.</small></label><div class="form-actions"><button type="button" class="btn" id="cancelQuickNote">Cancel</button><button class="btn primary">Save note</button></div></div>`;$('#modal').classList.remove('hidden');$('#cancelQuickNote').onclick=closeModal;$('#quickContactNote').focus();$('#modalForm').onsubmit=async event=>{event.preventDefault();const note=$('#quickContactNote').value.trim();if(!note)return toast('Type a note first',true);const button=event.submitter;button.disabled=true;button.textContent='Saving…';try{await api('/activities',{method:'POST',body:JSON.stringify({contact_id:contact.id,type:'Note',direction:'',subject:note,body:note,occurred_at:new Date().toISOString()})});closeModal();toast(`Note saved for ${contact.first_name}`)}catch(error){button.disabled=false;button.textContent='Save note';toast(error.message||'Note could not be saved',true)}}}
