function assistantDocumentDestination(prompt){const lower=String(prompt||'').toLowerCase();if(!/\b(?:upload|attach|add|save)\b/.test(lower)||!(/\b(?:document|file|pdf|report|agreement|disclosure|letter|contract)\b/.test(lower)))return null;const contact=assistantFindContact(prompt),listing=assistantFindListing(prompt),transaction=(state.data.transactions||[]).find(item=>{const property=String(item.property||'').toLowerCase(),street=property.split(',')[0];return street&&lower.includes(street)||property.match(/\b\d{3,5}\b/)?.[0]&&lower.includes(property.match(/\b\d{3,5}\b/)[0])}),task=(state.data.tasks||[]).find(item=>!item._calendar&&String(item.title||'').length>3&&lower.includes(String(item.title).toLowerCase()));if(/\b(?:general|unassigned|document center)\b/.test(lower))return {kind:'general',id:null,label:'General documents'};if(transaction)return {kind:'transaction',id:transaction.id,label:transaction.property};if(listing)return {kind:'listing',id:listing.id,label:listing.address};if(contact)return {kind:'contact',id:contact.id,label:`${contact.first_name} ${contact.last_name}`};if(task)return {kind:'task',id:task.id,label:task.title};return null}
