const bindAssistantActionsBeforeDocuments=bindAssistantActions;
bindAssistantActions=()=>{bindAssistantActionsBeforeDocuments();$$('.assistant-upload-document').forEach(button=>button.onclick=()=>{const destination=JSON.parse(decodeURIComponent(button.dataset.documentDestination));openDocumentManager(destination.kind,destination.id,destination.label)})};

