function notificationTaskId(item){return Number(item.task_id||String(item.source_id||'').match(/^task-(\d+)-/)?.[1]||0)}
function taskReminderAt(task){const due=new Date(task?.due_at),minutes=Number(task?.reminder_minutes||0);return !minutes||Number.isNaN(due.getTime())?null:new Date(due.getTime()-minutes*60000)}
async function openNotificationTask(taskId){await load('contacts','tasks','listings');const task=(state.data.tasks||[]).find(item=>!item._calendar&&Number(item.id)===Number(taskId));if(!task)return toast('That task is no longer available',true);openForm('tasks',task,task.id)}
async function ensureOperationalNotifications(){await load('tasks','transactions','notifications');const existing=new Set((state.data.notifications||[]).map(x=>x.source_id)),now=new Date(),today=now.toISOString().slice(0,10),inSeven=new Date(Date.now()+7*864e5).toISOString().slice(0,10),toCreate=[];for(const task of state.data.tasks||[]){if(task._calendar||task.status!=='open'||!task.due_at)continue;const reminderAt=taskReminderAt(task);if(!reminderAt||now<reminderAt)continue;const due=new Date(task.due_at),source=`task-${task.id}-${String(task.due_at).replace(/[^0-9]/g,'')}-${Number(task.reminder_minutes)}`;if(!existing.has(source))toCreate.push({type:'task_due',source_id:source,task_id:task.id,contact_id:task.contact_id||null,title:now>due?'Overdue task':'Task reminder',message:`${task.title} · ${fmtDateTime(task.due_at)}`,due_at:task.due_at,read:false})}for(const tx of state.data.transactions||[]){const day=calendarKey(tx.closing_date);if(!day||day<today||day>inSeven||tx.status==='Closed')continue;const source=`closing-${tx.id}-${day}`;if(!existing.has(source))toCreate.push({type:'closing_soon',source_id:source,title:'Closing date approaching',message:`${tx.property} · ${fmtDate(tx.closing_date)}`,read:false})}for(const item of toCreate)await api('/notifications',{method:'POST',body:JSON.stringify(item)});if(toCreate.length)await load('notifications')}
async function deliverDeviceNotifications(items){if(!('Notification'in window)||Notification.permission!=='granted')return;const prefs=notificationPreferences();let delivered={};try{delivered=JSON.parse(localStorage.getItem(NOTIFICATION_DELIVERED_KEY)||'{}')}catch{}const registration='serviceWorker'in navigator?await navigator.serviceWorker.ready.catch(()=>null):null;for(const item of items){if(item.read||prefs[item.type]===false||delivered[item.id]===item.created_at||item.type==='task_due'&&/^task-\d+-\d{4}-\d{2}-\d{2}$/.test(String(item.source_id||'')))continue;const taskId=notificationTaskId(item),task=taskId?(state.data.tasks||[]).find(entry=>!entry._calendar&&Number(entry.id)===taskId):null;if(item.type==='task_due'&&task){const reminderAt=taskReminderAt(task);if(!reminderAt||new Date()<reminderAt)continue}const url=new URL(location.href);if(taskId){url.searchParams.set('openTask',taskId);url.hash='tasks'}const options={body:item.message||'',icon:'./icon.svg',badge:'./icon.svg',tag:`crm-${item.id}`,data:{contact_id:item.contact_id||null,task_id:taskId||null,url:url.href}};if(registration)await registration.showNotification(item.title||'CRM notification',options);else{const alert=new Notification(item.title||'CRM notification',options);alert.onclick=()=>{window.focus();if(taskId)openNotificationTask(taskId)}}delivered[item.id]=item.created_at||true}localStorage.setItem(NOTIFICATION_DELIVERED_KEY,JSON.stringify(delivered))}
async function enableDeviceNotifications(){if(!('Notification'in window))return toast('Device alerts are not supported in this browser',true);const permission=await Notification.requestPermission();if(permission==='granted'){toast('Device alerts enabled');await refreshNotifications()}else toast('Notifications were not enabled. Check this site in device settings.',true)}
async function refreshNotifications(){
 await ensureOperationalNotifications();
 const notifications=(await api('/notifications')).sort((a,b)=>String(b.created_at||'').localeCompare(String(a.created_at||''))),unread=notifications.filter(x=>!x.read).length,badgeEl=$('#notificationBadge'),panel=$('#notificationPanel');
 badgeEl.textContent=unread>99?'99+':unread;badgeEl.hidden=!unread;
 const permission='Notification'in window?Notification.permission:'unsupported';panel.innerHTML=`<div class="panel-head"><h3>Notifications</h3>${unread?'<button class="btn" id="markNotificationsRead">Mark all read</button>':''}</div><div class="notification-device"><div><strong>Device alerts</strong><small>${permission==='granted'?'Enabled on this device':permission==='denied'?'Blocked in device settings':'Get open-house and due-date alerts outside the CRM.'}</small></div>${permission==='default'?'<button class="btn primary" id="enableDeviceNotifications">Enable</button>':''}</div>${notifications.length?notifications.slice(0,30).map(x=>`<div class="notification-entry ${x.read?'read':'unread'}" data-notification-id="${x.id}" data-contact-id="${x.contact_id||''}" data-task-id="${notificationTaskId(x)||''}"><span class="dot"></span><div><p>${esc(x.title||'CRM notification')}</p><small>${esc(x.message||'')}</small><small>${fmtDateTime(x.created_at)}</small>${x.action_phone&&x.action_body?`<a class="btn notification-action" href="sms:${phoneHref(x.action_phone)}?&body=${encodeURIComponent(x.action_body)}">${esc(x.action_label||'Send Text')}</a>`:''}</div></div>`).join(''):`<div class="empty"><strong>No notifications</strong>Open-house sign-ins and due items will appear here.</div>`}`;
 if($('#enableDeviceNotifications'))$('#enableDeviceNotifications').onclick=enableDeviceNotifications;
 $$('.notification-action',panel).forEach(link=>link.onclick=async e=>{e.stopPropagation();const entry=link.closest('.notification-entry'),id=Number(entry.dataset.notificationId);await api('/notifications/'+id,{method:'PUT',body:JSON.stringify({read:true,read_at:new Date().toISOString()})});toast('Thank-you text opened — tap Send in Messages')});
 $$('.notification-entry',panel).forEach(entry=>entry.onclick=async()=>{const id=Number(entry.dataset.notificationId),taskId=Number(entry.dataset.taskId||0);await api('/notifications/'+id,{method:'PUT',body:JSON.stringify({read:true,read_at:new Date().toISOString()})});panel.classList.add('hidden');if(taskId)await openNotificationTask(taskId);else if(entry.dataset.contactId)showContact(Number(entry.dataset.contactId));else await refreshNotifications()});
 if($('#markNotificationsRead'))$('#markNotificationsRead').onclick=async()=>{for(const item of notifications.filter(x=>!x.read))await api('/notifications/'+item.id,{method:'PUT',body:JSON.stringify({read:true,read_at:new Date().toISOString()})});await refreshNotifications()};
 await deliverDeviceNotifications(notifications);
}
$('#notificationButton').onclick=async e=>{e.stopPropagation();await refreshNotifications();$('#notificationPanel').classList.toggle('hidden')};
document.addEventListener('click',e=>{if(!e.target.closest('#notificationPanel')&&!e.target.closest('#notificationButton'))$('#notificationPanel').classList.add('hidden')});
document.addEventListener('click',e=>{if(!offlineMode)return;const exportButton=e.target.closest('#exportBtn');if(exportButton){e.preventDefault();e.stopImmediatePropagation();exportOfflineBackup();return}const link=e.target.closest('a[href*="-documents/"][href$="/download"]');if(link){e.preventDefault();e.stopImmediatePropagation();downloadOfflineDocument(link.getAttribute('href'))}},true);
document.addEventListener('click',e=>{const action=e.target.closest('[data-comm-kind][data-contact-id]');if(!action)return;const type=action.dataset.commKind,subject=type==='Call'?'Call initiated':type==='Text'?'Text message opened':'Email draft opened';api('/activities',{method:'POST',body:JSON.stringify({contact_id:Number(action.dataset.contactId),type,direction:'Outgoing',subject,body:'Initiated from the CRM. Add a note afterward if the conversation was completed.',occurred_at:new Date().toISOString()})}).catch(console.error)},true);
document.addEventListener('click',e=>{const n=e.target.closest('.navitem');if(n)go(n.dataset.view)});$('#quickAdd').onclick=()=>openForm('contacts');$('#closeModal').onclick=closeModal;$('#modal').onclick=e=>{if(e.target.id==='modal')closeModal()};$('#menuBtn').onclick=()=>$('.sidebar').classList.contains('open')?closeMenu():openMenu();$('#closeMenuBtn').onclick=closeMenu;$('#menuBackdrop').onclick=closeMenu;
function syncMobileModalViewport(){const height=Math.floor(window.visualViewport?.height||window.innerHeight);document.documentElement.style.setProperty('--crm-modal-height',`${height}px`)}
syncMobileModalViewport();window.addEventListener('resize',syncMobileModalViewport);window.visualViewport?.addEventListener('resize',syncMobileModalViewport);window.visualViewport?.addEventListener('scroll',syncMobileModalViewport);
document.addEventListener('focusin',e=>{if(!e.target.closest('#modalForm')||!matchMedia('(max-width:720px)').matches)return;syncMobileModalViewport();setTimeout(()=>e.target.scrollIntoView({block:'center',behavior:'smooth'}),120)});
let searchTimer;$('#globalSearch').oninput=e=>{clearTimeout(searchTimer);const q=e.target.value.trim();$('.search-results')?.remove();if(q.length<2)return;searchTimer=setTimeout(async()=>{const d=await api('/search?q='+encodeURIComponent(q));const box=document.createElement('div');box.className='search-results';box.innerHTML=[...d.contacts.map(c=>`<div class="result" data-contact="${c.id}"><b>${esc(c.first_name)} ${esc(c.last_name)}</b><small>Contact · ${esc(c.email||c.phone||c.source)}</small></div>`),...d.properties.map(x=>`<div class="result"><b>${esc(x.label)}</b><small>${x.kind} · ${esc(x.detail)}</small></div>`),...d.stages.map(x=>`<div class="result" data-contact="${x.contact_id}"><b>${esc(x.contact_name)}</b><small>${esc(x.type)} · ${esc(x.stage)}</small></div>`)].join('')||empty('No matches','Try another name, property, or stage.');document.body.append(box);$$('[data-contact]',box).forEach(x=>x.onclick=()=>{box.remove();$('#globalSearch').value='';showContact(Number(x.dataset.contact))})},250)};
document.addEventListener('keydown',e=>{if((e.metaKey||e.ctrlKey)&&e.key==='k'){e.preventDefault();$('#globalSearch').focus()}if(e.key==='Escape'){closeModal();$('.search-results')?.remove()}});if('serviceWorker'in navigator){let refreshing=false;navigator.serviceWorker.addEventListener('controllerchange',()=>{if(refreshing)return;refreshing=true;location.reload()});navigator.serviceWorker.addEventListener('message',event=>{if(event.data?.type==='OPEN_NOTIFICATION'&&event.data.data?.task_id)openNotificationTask(Number(event.data.data.task_id))});navigator.serviceWorker.register('./sw.js?v=95',{updateViaCache:'none'}).then(registration=>{registration.update();setInterval(()=>registration.update(),300000)}).catch(console.error)}enhanceOfflineControls();const requestedTask=Number(new URLSearchParams(location.search).get('openTask')||0);go(location.hash.slice(1).split('?')[0]||'dashboard').then(()=>{if(requestedTask)openNotificationTask(requestedTask)});refreshNotifications();setInterval(()=>{if(document.visibilityState==='visible')refreshNotifications().catch(console.error)},60000);
